24: function getTFGCoverTexture() {
25:   if (_tfgCoverTex) return _tfgCoverTex;
26:   const canvas = document.createElement("canvas");
27:   canvas.width = 512;
28:   canvas.height = 768;
29:   const ctx = canvas.getContext("2d");
30: 
31:   // Cuero azul institucional profundo UNCo
32:   ctx.fillStyle = "#091a32";
33:   ctx.fillRect(0, 0, 512, 768);
34: 
35:   // Grano sutil de encuadernación en piel
36:   for (let i = 0; i < 14000; i++) {
37:     const x = Math.random() * 512;
38:     const y = Math.random() * 768;
39:     const alpha = Math.random() * 0.07;
40:     ctx.fillStyle = Math.random() > 0.5 ? `rgba(255,255,255,${alpha})` : `rgba(0,0,0,${alpha})`;
41:     ctx.fillRect(x, y, 1.5, 1.5);
42:   }
43: 
44:   // Marco perimetral con filetes dorados estampados al calor
45:   ctx.strokeStyle = "#d4af37";
46:   ctx.lineWidth = 4;
47:   ctx.strokeRect(24, 24, 512 - 48, 768 - 48);
48:   ctx.lineWidth = 1.5;
49:   ctx.strokeRect(34, 34, 512 - 68, 768 - 68);
50: 
51:   // Florones dorados en las esquinas
52:   const corners = [[34, 34], [512 - 34, 34], [34, 768 - 34], [512 - 34, 768 - 34]];
53:   ctx.fillStyle = "#d4af37";
54:   corners.forEach(([cx, cy]) => {
55:     ctx.beginPath();
56:     ctx.arc(cx, cy, 6, 0, Math.PI * 2);
57:     ctx.fill();
58:   });
59: 
60:   _tfgCoverTex = new THREE.CanvasTexture(canvas);
61:   return _tfgCoverTex;
62: }
